node -e "import('ajv').then(({Ajv}) => {
  const ajv = new Ajv({strict: false, validateFormats: false, allErrors: true});
  const validate = ajv.compile({
    type: 'object',
    properties: {
      location: {type: 'string'},
      units: {type: 'string', enum: ['celsius', 'fahrenheit']},
      nested: {type: 'object', properties: {count: {type: 'number'}}, required: ['count']}
    },
    required: ['location']
  });
  validate({units: 'kelvin', nested: {count: 'bad'}});
  console.log('errors:', JSON.stringify(validate.errors, null, 2));
  console.log('errorsText:', ajv.errorsText(validate.errors));
})"
